#include "PluginEditor.h"
static const juce::Colour bg(8,5,15), purple(178,35,255), glow(235,145,255), panel(24,12,36);
SpectrumMeterAudioProcessorEditor::SpectrumMeterAudioProcessorEditor(SpectrumMeterAudioProcessor& p):AudioProcessorEditor(&p),proc(p){
 setResizable(true,true);setResizeLimits(720,420,2200,1300);setSize(1200,650);
 auto setup=[](juce::ComboBox& c,std::initializer_list<const char*> a){int i=1;for(auto s:a)c.addItem(s,i++);c.setSelectedId(1);c.setColour(juce::ComboBox::backgroundColourId,panel);c.setColour(juce::ComboBox::textColourId,juce::Colours::white);c.setColour(juce::ComboBox::outlineColourId,purple);c.setColour(juce::ComboBox::arrowColourId,glow);};
 setup(mode,{"FFT","CURVE","WATERFALL","SONOGRAM"});setup(channel,{"L + R","LEFT","RIGHT"});setup(speed,{"SLOW","MEDIUM","FAST"});setup(scale,{"dB","RMS"});setup(range,{"-96 dB / +12 dB","-72 dB / 0 dB","-48 dB / 0 dB"});setup(resolution,{"16384","8192","4096","2048"});setup(slope,{"SMOOTH","FLAT","3 dB / OCT"});
 for(auto*c:{&mode,&channel,&speed,&scale,&range,&resolution,&slope})addAndMakeVisible(c);
 for(auto*b:{&fft,&curve,&waterfall,&sono}){b->setColour(juce::TextButton::buttonColourId,panel);b->setColour(juce::TextButton::textColourOffId,juce::Colours::white);addAndMakeVisible(b);}
 fft.onClick=[this]{view=0;mode.setSelectedId(1);};curve.onClick=[this]{view=1;mode.setSelectedId(2);};waterfall.onClick=[this]{view=2;mode.setSelectedId(3);};sono.onClick=[this]{view=3;mode.setSelectedId(4);};mode.onChange=[this]{view=mode.getSelectedId()-1;};average.setToggleState(true,juce::dontSendNotification);addAndMakeVisible(average);startTimerHz(30);
}
float SpectrumMeterAudioProcessorEditor::dbAt(float f)const{int k=juce::jlimit(1,SpectrumMeterAudioProcessor::bins-1,(int)(f*SpectrumMeterAudioProcessor::size/proc.sampleRate()));return data[(size_t)k];}
void SpectrumMeterAudioProcessorEditor::timerCallback(){proc.copySpectrum(data);repaint();}
void SpectrumMeterAudioProcessorEditor::paint(juce::Graphics& g){
 auto b=getLocalBounds().toFloat();g.fillAll(bg);g.setColour(panel);g.fillRoundedRectangle(b.reduced(3),12);g.setColour(purple);g.drawRoundedRectangle(b.reduced(3),12,2);
 g.setColour(glow);g.drawLine(18,82,b.getWidth()-18,82,1.4f);g.setColour(juce::Colours::white);g.setFont(juce::Font(20,juce::Font::bold));g.drawText("S P E C T R U M   M E T E R",28,20,400,32,juce::Justification::centredLeft);g.setColour(glow);g.setFont(juce::Font(22,juce::Font::bold));g.drawText("MS",b.getCentreX()-40,8,80,36,juce::Justification::centred);g.setFont(10);g.drawText("PROD BY MOTI SIMON",b.getCentreX()-80,43,160,18,juce::Justification::centred);
 juce::Rectangle<float> p(55,105,b.getWidth()-80,b.getHeight()-190);g.setColour(juce::Colour(4,3,9));g.fillRect(p);
 for(int d=12;d>=-96;d-=12){float y=juce::jmap((float)d,12.0f,-96.0f,p.getY(),p.getBottom());g.setColour(juce::Colour(93,48,122).withAlpha(.48f));g.drawHorizontalLine((int)y,p.getX(),p.getRight());g.setColour(juce::Colours::white);g.setFont(11);g.drawText(juce::String(d),8,(int)y-7,38,14,juce::Justification::centredRight);}
 const float fs[]={20,50,100,200,500,1000,2000,5000,10000,20000};for(float f:fs){float x=p.getX()+std::log(f/20)/std::log(1000.0f)*p.getWidth();g.setColour(juce::Colour(93,48,122).withAlpha(.5f));g.drawVerticalLine((int)x,p.getY(),p.getBottom());g.setColour(juce::Colours::white);g.setFont(11);juce::String t=f>=1000?juce::String(f/1000, f>=10000?0:1)+"k":juce::String((int)f);g.drawText(t,(int)x-18,(int)p.getBottom()+7,36,15,juce::Justification::centred);}
 juce::Path line,fill;bool first=true;for(int x=0;x<(int)p.getWidth();++x){float f=20*std::pow(1000.0f,x/juce::jmax(1.0f,p.getWidth()-1));float db=dbAt(f);float y=juce::jmap(juce::jlimit(-96.0f,12.0f,db),-96.0f,12.0f,p.getBottom(),p.getY());if(first){line.startNewSubPath(p.getX()+x,y);fill.startNewSubPath(p.getX()+x,p.getBottom());fill.lineTo(p.getX()+x,y);first=false;}else{line.lineTo(p.getX()+x,y);fill.lineTo(p.getX()+x,y);}}
 fill.lineTo(p.getRight(),p.getBottom());fill.closeSubPath();g.setGradientFill(juce::ColourGradient(purple.withAlpha(.82f),0,p.getY(),purple.withAlpha(.02f),0,p.getBottom(),false));g.fillPath(fill);g.setColour(glow);g.strokePath(line,juce::PathStrokeType(view==1?2.3f:1.5f));g.setColour(purple);g.drawRect(p,1.2f);
 g.setColour(panel);g.fillRoundedRectangle(14,b.getHeight()-57,b.getWidth()-28,43,8);g.setColour(purple);g.drawRoundedRectangle(14,b.getHeight()-57,b.getWidth()-28,43,1.0f);
}
void SpectrumMeterAudioProcessorEditor::resized(){auto b=getLocalBounds();mode.setBounds(b.getWidth()-440,42,100,28);channel.setBounds(b.getWidth()-330,42,95,28);speed.setBounds(b.getWidth()-225,42,90,28);int y=b.getHeight()-50;scale.setBounds(35,y,75,28);range.setBounds(120,y,135,28);resolution.setBounds(265,y,92,28);fft.setBounds(b.getWidth()/2-235,y,78,28);curve.setBounds(b.getWidth()/2-150,y,90,28);waterfall.setBounds(b.getWidth()/2-53,y,112,28);sono.setBounds(b.getWidth()/2+66,y,112,28);slope.setBounds(b.getWidth()-300,y,125,28);average.setBounds(b.getWidth()-165,y,130,28);}
